'use strict';

/* eslint n/no-unsupported-features/es-builtins: ["error", {"version": ">=12.0.0"}] */

/* eslint n/no-unsupported-features/node-builtins: ["error", {"version": ">=12.0.0"}] */


// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var tryRequire = require( '@stdlib/utils/try-require' );
var factory = require( './../lib/factory.js' );
var configured = require( './../lib/can_use_native.js' );
var base = require( './../lib/base.js' );
var run = require( './helpers.js' );


// VARIABLES //

var addon = tryRequire( resolve(__dirname, '../src/addon.node') );
var opts = {
	'skip': (addon instanceof Error)
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual(typeof addon, 'function');

	t.end();
});

tape( 'dpbtf2: actual compiled native reference and independent equations', opts, function test( t ) {
	var native;
	var calls;
	calls = 0;
	native = factory( function backend() {
		calls += 1;
		return addon.apply( null, arguments );
	}, configured(addon.lapackIntegerBytes, addon.blasIntegerBytes), base );
	run( t, native );
	t.comment( 'Actual compiled addon calls: '+calls );
	t.ok( (calls > 600), 'actual compiled addon dispatched for positive fixtures' );
	t.end();
});
tape( 'dpbtf2: raw bridge prewrite gates and no narrowing enum alias', opts, function test( t ) {
	var before;
	var a = new Float64Array( [4, 2, 10, 3, 17, 99] );
	before = Array.prototype.slice.call(a);
	t.throws( function bad() {
		addon(4294967417, 3, 1, a, 1, 2, 0);
	}, Error, 'selector before enum narrowing' );
	t.throws( function bad() {
		addon(122, 3, 1, a, 1, 1, 0);
	}, RangeError, 'colliding view before mutation' );
	t.throws( function bad() {
		addon(122, 3, 1, a, 1, 2, -1);
	}, RangeError, 'negative envelope before mutation' );
	t.deepEqual( Array.prototype.slice.call(a), before, 'raw rejection keeps entire AB unchanged' );
	t.strictEqual( addon(121, 0, 0, null, null, null, null), 0, 'raw valid empty ignores storage and metadata' );
	t.end();
});
